import QtQuick
import QtQuick.Controls
import QtQuick.Window

Row {
    id: root
    required property var targetWindow
    objectName: "windowControls"
    spacing: 10
    HoverHandler { id: groupHover }
    Repeater {
        model: ["fullscreen", "minimize", "close"]
        delegate: AbstractButton {
            id: button
            required property string modelData
            objectName: "window" + modelData + "Button"
            width: 22; height: 32
            hoverEnabled: true
            focusPolicy: Qt.StrongFocus
            Accessible.name: modelData === "fullscreen"
                ? (root.targetWindow.visibility === Window.FullScreen ? qsTr("Exit full screen") : qsTr("Full screen"))
                : modelData === "minimize" ? qsTr("Minimize") : qsTr("Close")
            ToolTip.visible: hovered
            ToolTip.text: Accessible.name
            ToolTip.delay: 700
            onClicked: {
                if (modelData === "fullscreen") root.targetWindow.toggleFullScreen()
                else if (modelData === "minimize") root.targetWindow.showMinimized()
                else root.targetWindow.close()
            }
            background: Item {
                Rectangle {
                    anchors.centerIn: parent
                    width: 18; height: 18; radius: 9
                    color: button.modelData === "fullscreen" ? "#2fc866" : button.modelData === "minimize" ? "#ffbf18" : "#ff5f57"
                    border.width: button.activeFocus ? 2 : 1
                    border.color: button.activeFocus ? AppTheme.text : Qt.darker(color, 1.28)
                    scale: button.down ? .88 : button.hovered ? 1.04 : 1
                    Behavior on scale { NumberAnimation { duration: AppTheme.motionFast } }
                    Item {
===
KosApplicationWindow {
    id: root

    modernDesign: true
    visible: true
    // The bare attached ToolTip renders the installed Basic style verbatim,
    // whose panel is `palette.toolTipBase` + `palette.toolTipText` (R134). The
    // app sets no palette, so on the dark leg that leaks a pure-white panel
    // with near-black ink onto a (30,30,30) window. Theme the two tooltip
    // slots per leg on the window palette: dark panel #3C3C3C (the tahoe
    // elevated lift over #1E1E1E) with #F2F2F2 ink; light panel #F2F2F2 (one
    // step below the white plane) with black ink. Radius stays Basic's 0
    // (square) — the reference has no tooltip at all (R063), so the choice is
    // ours and is recorded here for both legs.
    palette.toolTipBase: root.tahoeDark ? "#3C3C3C" : "#F2F2F2"
    palette.toolTipText: root.tahoe.labelPrimary
    title: qsTr("Calendar")
    width: 1100
    height: 720
    minimumWidth: 760
    minimumHeight: 540

    property date now: new Date()
    property date visibleMonth: new Date(new Date().getFullYear(), new Date().getMonth(), 1)
